import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
  useId,
  watch,
} from "vue";
import { animate, useMotionValue, type MotionValue } from "motion-v";
import { SPRING_GLIDE } from "../../../lib/ease";
import { useControllable, useReduced, type Content } from "../../shared";
import {
  DRAG_THRESHOLD,
  SURFACE_INSET,
  moveItem,
  sameOrder,
  tabGeometry,
} from "./model";
export interface TabsItem {
  id: string;
  label: string;
  icon?: Content;
  content: Content;
  disabled?: boolean;
}
interface Props {
  items: TabsItem[];
  modelValue?: string | null;
  defaultValue?: string | null;
}
