    reduce,
    uid,
    root,
    rail,
    ordered,
    active,
    surfaceWidth,
    draggingId,
    dragLeft,
    surfaceLeft,
    geometry,
    slotLefts,
    tabs,
    visualIndex,
    register,
    startDrag,
    moveDrag,
    finish,
    clickTab,
    key,
